import L from 'leaflet'
import { setWorkerUrl, type Map as GLMap } from 'maplibre-gl'
import maplibreWorkerUrl from 'maplibre-gl/dist/maplibre-gl-worker.mjs?url'
import { maplibreGL } from '@maplibre/maplibre-gl-leaflet'
import type { Building, PathPoint, Zone } from './types'
import { asset } from './asset'

// MapLibre v6 loads its worker from a sibling file; point it at the Vite-emitted asset.
setWorkerUrl(maplibreWorkerUrl)

const MAHILIOU: L.LatLngExpression = [53.9006, 30.3314]
const BASEMAP_STYLE = 'https://tiles.openfreemap.org/styles/positron'

/** Positron labels default to "latin\nnonlatin"; show Belarusian names, falling back to local. */
function preferBelarusianLabels(glMap: GLMap) {
  for (const layer of glMap.getStyle().layers) {
    if (layer.type !== 'symbol') continue
    const field = glMap.getLayoutProperty(layer.id, 'text-field')
    if (!field || !JSON.stringify(field).includes('name')) continue
    glMap.setLayoutProperty(layer.id, 'text-field', ['coalesce', ['get', 'name:be'], ['get', 'name']])
  }
}

type MarkerState = L.Marker & { __pin: string; __mapIcon?: string }

export interface MapController {
  map: L.Map
  setBuildings: (buildings: Building[], onSelect: (b: Building) => void) => void
  focusBuilding: (b: Building) => void
  setZones: (zones: Zone[]) => void
  highlight: (id: string | null) => void
}

/** Split path points into rings where `connected === false` starts a new one. */
function splitPathSegments(points: PathPoint[]): PathPoint[][] {
  const segments: PathPoint[][] = []
  let current: PathPoint[] = []
  for (const point of points) {
    if (point.connected === false && current.length > 0) {
      segments.push(current)
      current = []
    }
    current.push(point)
  }
  if (current.length > 0) segments.push(current)
  return segments
}

function toLatLngs(points: PathPoint[]): L.LatLngExpression[] {
  return points.map((p) => [p.lat, p.lon] as L.LatLngExpression)
}

function buildingIcon(pin: string, mapIcon: string | undefined, focused = false): L.DivIcon {
  if (mapIcon) {
    return L.divIcon({
      className: `kropki-marker kropki-marker--custom${focused ? ' is-focused' : ''}`,
      iconSize: [52, 56],
      iconAnchor: [26, 54],
      popupAnchor: [0, -48],
      html: `<img src="${asset(mapIcon)}" width="52" height="56" alt="" draggable="false" />`,
    })
  }
  const file = focused ? `${pin}_focus.svg` : `${pin}.svg`
  return L.divIcon({
    className: `kropki-marker${focused ? ' is-focused' : ''}`,
    iconSize: [28, 28],
    iconAnchor: [14, 14],
    popupAnchor: [0, -14],
    html: `<img src="${asset(`pins/${file}`)}" width="28" height="28" alt="" draggable="false" />`,
  })
}

export function createMap(container: HTMLElement): MapController {
  const map = L.map(container, {
    center: MAHILIOU,
    zoom: 13,
    minZoom: 11,
    maxZoom: 18,
    zoomControl: false,
  })

  L.control.zoom({ position: 'bottomright' }).addTo(map)

  // OpenFreeMap Positron: free, keyless vector basemap (CARTO light_all now requires an API key).
  const basemap = maplibreGL({ style: BASEMAP_STYLE }).addTo(map)
  const glMap = basemap.getMaplibreMap()
  glMap.on('style.load', () => preferBelarusianLabels(glMap))

  const buildingsLayer = L.layerGroup().addTo(map)
  const zonesLayer = L.layerGroup().addTo(map)
  const markers = new Map<string, MarkerState>()

  function highlight(id: string | null) {
    markers.forEach((marker, mid) => {
      marker.setIcon(buildingIcon(marker.__pin, marker.__mapIcon, mid === id))
      if (mid === id) marker.setZIndexOffset(1000)
      else marker.setZIndexOffset(marker.__mapIcon ? 200 : 0)
    })
  }

  function setBuildings(buildings: Building[], onSelect: (b: Building) => void) {
    buildingsLayer.clearLayers()
    markers.clear()
    for (const b of buildings) {
      const marker = L.marker([b.lat, b.lon], {
        icon: buildingIcon(b.pin, b.mapIcon),
        title: b.name,
        zIndexOffset: b.mapIcon ? 200 : 0,
      }) as MarkerState
      marker.__pin = b.pin
      marker.__mapIcon = b.mapIcon
      marker.on('click', () => {
        highlight(b.id)
        onSelect(b)
      })
      marker.addTo(buildingsLayer)
      markers.set(b.id, marker)
    }
  }

  function focusBuilding(b: Building) {
    map.setView([b.lat, b.lon], Math.max(map.getZoom(), 16), { animate: true })
    highlight(b.id)
  }

  function setZones(zones: Zone[]) {
    zonesLayer.clearLayers()
    for (const zone of zones) {
      for (const ring of splitPathSegments(zone.points)) {
        const latlngs = toLatLngs(ring)
        if (latlngs.length < 3) continue
        L.polygon(latlngs, {
          color: '#C45C26',
          weight: 1,
          fillColor: '#C45C26',
          fillOpacity: 0.12,
        })
          .bindTooltip(zone.name)
          .addTo(zonesLayer)
      }
    }
  }

  return {
    map,
    setBuildings,
    focusBuilding,
    setZones,
    highlight,
  }
}
